dtsPropsFor.Button:
variant?: 'primary' | 'secondary' | 'ghost' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  block?: boolean;
  /** Muestra un indicador y deshabilita, para que no se envíe dos veces. */
  loading?: boolean;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.Input:
invalid?: boolean;
  type?: string;
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  disabled?: boolean;
  required?: boolean;
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  className?: string;

dtsPropsFor.Field:
label: string;
  /** Ayuda que se muestra ANTES de escribir, no después de fallar. */
  hint?: React.ReactNode;
  error?: string | null;
  required?: boolean;
  /** Recibe los atributos que hay que poner en el control (id, aria-describedby, aria-invalid, required). */
  children: (props: {
    id: string;
    'aria-describedby': string | undefined;
    'aria-invalid': boolean | undefined;
    required: boolean;
  }) => React.ReactNode;

dtsPropsFor.Card:
title?: string;
  subtitle?: string;
  children: React.ReactNode;

dtsPropsFor.Switch:
checked: boolean;
  onChange: (checked: boolean) => void;
  label: string;
  disabled?: boolean;

dtsPropsFor.EmptyState:
title: string;
  description?: string;
  action?: React.ReactNode;

dtsPropsFor.Drawer:
open: boolean;
  title: string;
  description?: string;
  onClose: () => void;
  footer?: React.ReactNode;
  children: React.ReactNode;

dtsPropsFor.ConfirmDialog:
open: boolean;
  title: string;
  /** La consecuencia real, enunciada: «Se cerrarán sus sesiones abiertas». No «¿estás seguro?». */
  children: React.ReactNode;
  /** Texto del botón que confirma. Nombra la acción: «Activar Catálogo», «Desactivar usuario». Sin valor por defecto a propósito. */
  confirmLabel: string;
  danger?: boolean;
  busy?: boolean;
  onConfirm: () => void;
  onCancel: () => void;

dtsPropsFor.Toasts:
toasts: readonly {
    readonly id: number;
    readonly message: string;
    readonly tone: 'success' | 'danger';
  }[];

dtsPropsFor.Table:
columns: readonly {
    key: string;
    header: string;
    align?: 'left' | 'right';
    render: (row: any) => React.ReactNode;
  }[];
  rows: readonly any[];
  rowKey: (row: any) => string | number;
  /** Atenúa la fila. Para lo dado de baja, que se muestra pero no se oculta. */
  dimmed?: (row: any) => boolean;
  loading?: boolean;
  /** Qué enseñar cuando no hay nada. Con acción, no solo un texto. */
  empty?: React.ReactNode;
  pagination?: {
    page: number;
    totalPages: number;
    totalItems: number;
    onChange: (page: number) => void;
  };

dtsPropsFor.Pagination:
page: number;
  totalPages: number;
  totalItems: number;
  onChange: (page: number) => void;

dtsPropsFor.FailureAlert:
/** null o 'silent' no muestran nada: el fallo lo absorbe otra pantalla. */
  failure: {
    kind: 'inline' | 'validation' | 'forbidden' | 'silent';
    message: string;
    fieldErrors: Record<string, string> | null;
    blockedBy: string[] | null;
  } | null;

dtsPropsFor.Gallery:
items: readonly any[];
  itemKey: (item: any) => string | number;
  render: (item: any) => React.ReactNode;
  loading?: boolean;
  empty?: React.ReactNode;

dtsPropsFor.ModuleCard:
module: {
    code: string;
    displayName: string;
    description: string;
    version: string;
    isCore: boolean;
    isActive: boolean;
    activatedAt: string | null;
    deactivatedAt: string | null;
    /** Vencimiento de la licencia. Se muestra pero no se evalúa (fase 5). */
    expiresAt: string | null;
    displayOrder: number;
    hardDependencies: string[];
    softDependencies: string[];
    canActivate: boolean;
    canDeactivate: boolean;
    /** Qué lo impide: dependencias duras inactivas si no se puede activar, o módulos activos que dependen de él si no se puede desactivar. */
    blockedBy: string[];
    restartsAutomatically: boolean;
  };
  /** Nombres visibles por código, para poder nombrar a quien bloquea. */
  displayNames: ReadonlyMap<string, string>;
  /** Resaltada porque se ha llegado desde otra tarjeta. */
  highlighted: boolean;
  busy: boolean;
  onToggle: (module: unknown) => void;
  onJumpTo: (code: string) => void;
